import Darwin
import Foundation

/// Package and build caches across checkouts. A new worktree gets copy-on-write clones of its
/// source checkout's dependency folders (node_modules, Pods, SwiftPM clones), so it neither
/// downloads nor stores them again. The daily cleanup reports the shared package caches, trims
/// the ones over their cap, and removes Xcode and SwiftPM output nothing has used for a while.
/// Everything it removes is regenerated by the next build; it never touches tracked files.
enum BuildCaches {
    // MARK: - Build root

    /// `CANTRIP_BUILD_ROOT` (a build disk such as a NAS), when it is a folder this user can
    /// write. nil means build locally: the variable is unset, or the disk isn't mounted.
    static func buildRoot(_ environment: [String: String] = ProcessInfo.processInfo.environment) -> URL? {
        guard let value = environment["CANTRIP_BUILD_ROOT"], !value.isEmpty else { return nil }
        let path = (value as NSString).expandingTildeInPath
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: path, isDirectory: &isDirectory), isDirectory.boolValue,
              access(path, W_OK) == 0 else { return nil }
        return URL(fileURLWithPath: path, isDirectory: true)
    }

    /// Puts the `buildRoot` setting in this process's environment, which every agent and shell it
    /// starts inherits. At launch a value already set (by a terminal) wins.
    static func exportBuildRoot(_ value: String?, replacing: Bool = false) {
        guard replacing || ProcessInfo.processInfo.environment["CANTRIP_BUILD_ROOT"] == nil else { return }
        if let value, !value.isEmpty {
            setenv("CANTRIP_BUILD_ROOT", (value as NSString).expandingTildeInPath, 1)
        } else if replacing {
            unsetenv("CANTRIP_BUILD_ROOT")
        }
    }

    // MARK: - Seeding worktrees

    /// A dependency folder and the lockfiles beside it. One must exist, be byte-identical in both
    /// checkouts, and the source's folder must hold what it pins (`isInstalled`), or the clone
    /// could hold other versions than the worktree asks for. Empty when the tool reconciles the
    /// folder itself (SwiftPM checks out its pins on every resolve).
    struct DependencyKind {
        let folder: String
        let lockfiles: [String]
    }

    static let dependencyKinds = [
        DependencyKind(folder: "node_modules", lockfiles: ["npm-shrinkwrap.json", "package-lock.json", "pnpm-lock.yaml"]),
        DependencyKind(folder: "Pods", lockfiles: ["Podfile.lock"]),
        DependencyKind(folder: ".spm", lockfiles: []),
    ]

    /// SwiftPM's pins inside a generated (git-ignored) Xcode project, so the worktree resolves the
    /// same versions as its source instead of the newest ones.
    static let projectPins = "project.xcworkspace/xcshareddata/swiftpm/Package.resolved"

    /// Folders the search for dependency folders never enters.
    private static let unsearched: Set<String> = [".git", "build", ".build", "DerivedData", "Carthage", ".gradle"]

    struct Candidate: Equatable {
        /// Relative to the checkout.
        var path: String
        var lockfiles: [String]
        var isDirectory = true
    }

    /// Dependency folders (and pinned project files) in `checkout`, at most `maxDepth` folders deep.
    /// Nested repositories (submodules, other checkouts) are left to their own checkout.
    static func candidates(in checkout: URL, maxDepth: Int = 4) -> [Candidate] {
        let fm = FileManager.default
        let root = checkout.standardizedFileURL
        let keys: [URLResourceKey] = [.isDirectoryKey, .isSymbolicLinkKey]
        guard let walker = fm.enumerator(at: root, includingPropertiesForKeys: keys, options: [],
                                         errorHandler: { _, _ in true }) else { return [] }
        let kinds = Dictionary(uniqueKeysWithValues: dependencyKinds.map { ($0.folder, $0) })
        var found: [Candidate] = []
        for case let url as URL in walker {
            guard let values = try? url.resourceValues(forKeys: Set(keys)), values.isDirectory == true,
                  values.isSymbolicLink != true else { continue }
            let relative = url.standardizedFileURL.pathComponents.dropFirst(root.pathComponents.count)
            let name = url.lastPathComponent
            if let kind = kinds[name] {
                found.append(Candidate(path: relative.joined(separator: "/"), lockfiles: kind.lockfiles))
                walker.skipDescendants()
                continue
            }
            if name.hasSuffix(".xcodeproj") {
                let pins = url.appendingPathComponent(projectPins)
                if fm.fileExists(atPath: pins.path) {
                    found.append(Candidate(path: (Array(relative) + [projectPins]).joined(separator: "/"),
                                           lockfiles: [], isDirectory: false))
                }
                walker.skipDescendants()
                continue
            }
            if unsearched.contains(name) || name.hasPrefix(".") || relative.count >= maxDepth
                || fm.fileExists(atPath: url.appendingPathComponent(".git").path) {
                walker.skipDescendants()
            }
        }
        return found
    }

    struct SeedResult: Equatable {
        var seeded: [String] = []
        /// Path and why it wasn't cloned.
        var skipped: [(path: String, reason: String)] = []

        static func == (a: SeedResult, b: SeedResult) -> Bool {
            a.seeded == b.seeded && a.skipped.map(\.path) == b.skipped.map(\.path)
                && a.skipped.map(\.reason) == b.skipped.map(\.reason)
        }
    }

    /// Clones dependency folders into `worktree` with `clonefile`, which shares their blocks until
    /// either side changes a file. Each comes from the first of `sources` (other checkouts of the
    /// repository) whose copy is current for the worktree's lockfile. Only paths git ignores in the
    /// worktree, and that it doesn't have yet, are cloned; the rest is left to the usual install.
    /// Nothing is ever copied in full: on another volume the folder is skipped.
    static func seed(worktree: String, from sources: [String], git: String = "/usr/bin/git",
                     dryRun: Bool = false) -> SeedResult {
        let fm = FileManager.default
        let worktreeURL = URL(fileURLWithPath: worktree, isDirectory: true)
        let own = StorageUpkeep.resolved(worktree)
        var result = SeedResult()
        var chosen: [(candidate: Candidate, source: URL)] = []
        var reasons: [String: String] = [:]
        var order: [String] = []
        for source in sources where StorageUpkeep.resolved(source) != own {
            let sourceURL = URL(fileURLWithPath: source, isDirectory: true)
            for candidate in candidates(in: sourceURL) where !chosen.contains(where: { $0.candidate.path == candidate.path }) {
                if !order.contains(candidate.path) { order.append(candidate.path) }
                if let reason = unseedable(candidate, from: sourceURL, into: worktreeURL) {
                    // The first source's reason is the one worth reporting.
                    if reasons[candidate.path] == nil { reasons[candidate.path] = reason }
                    continue
                }
                chosen.append((candidate, sourceURL))
            }
        }
        let ignored = ignoredPaths(chosen.map { $0.candidate.isDirectory ? $0.candidate.path + "/" : $0.candidate.path },
                                   in: worktree, git: git)
        for (candidate, source) in chosen {
            guard ignored.contains(candidate.isDirectory ? candidate.path + "/" : candidate.path) else {
                // An untracked clone would end up in the child's commit.
                reasons[candidate.path] = "git doesn't ignore it"
                continue
            }
            let target = worktreeURL.appendingPathComponent(candidate.path)
            if !dryRun {
                try? fm.createDirectory(at: target.deletingLastPathComponent(), withIntermediateDirectories: true)
                let from = source.appendingPathComponent(candidate.path).path
                guard clonefile(from, target.path, UInt32(CLONE_NOFOLLOW)) == 0 else {
                    reasons[candidate.path] = "clonefile failed: \(String(cString: strerror(errno)))"
                    continue
                }
            }
            reasons[candidate.path] = nil
            result.seeded.append(candidate.path)
        }
        result.skipped = order.compactMap { path in reasons[path].map { (path, $0) } }
        return result
    }

    /// Why `candidate` can't come from `source`, or nil when it can.
    static func unseedable(_ candidate: Candidate, from source: URL, into worktree: URL) -> String? {
        let fm = FileManager.default
        let target = worktree.appendingPathComponent(candidate.path)
        let parent = target.deletingLastPathComponent()
        if (try? target.checkResourceIsReachable()) == true
            || (try? fm.destinationOfSymbolicLink(atPath: target.path)) != nil {
            return "the worktree already has it"
        }
        // The pins file goes into a generated project folder the worktree doesn't have yet.
        let home = candidate.isDirectory ? parent : worktree.appendingPathComponent(
            String(candidate.path.dropLast(projectPins.count + 1))).deletingLastPathComponent()
        guard fm.fileExists(atPath: home.path) else { return "its folder isn't in the worktree" }
        guard !candidate.lockfiles.isEmpty else { return nil }
        let folder = source.appendingPathComponent(candidate.path)
        let sourceParent = folder.deletingLastPathComponent()
        guard let lockfile = candidate.lockfiles.first(where: {
            fm.fileExists(atPath: sourceParent.appendingPathComponent($0).path)
        }) else { return "no lockfile Cantrip can check beside it" }
        guard fm.contentsEqual(atPath: sourceParent.appendingPathComponent(lockfile).path,
                               andPath: parent.appendingPathComponent(lockfile).path) else { return "\(lockfile) differs" }
        // patch-package edits installed packages from patches/.
        let patches = sourceParent.appendingPathComponent("patches")
        if fm.fileExists(atPath: patches.path),
           !fm.contentsEqual(atPath: patches.path, andPath: parent.appendingPathComponent("patches").path) {
            return "patches/ differs"
        }
        guard isInstalled(folder, lockfile: sourceParent.appendingPathComponent(lockfile)) else {
            return "the copy in \(source.path) isn't installed from its \(lockfile)"
        }
        return nil
    }

    /// Whether `folder` holds what `lockfile` pins: npm's hidden lockfile agrees on every package,
    /// pnpm's copy of its lockfile is the same, or CocoaPods' manifest equals Podfile.lock (the
    /// check `pod install` makes). An install older than its lockfile fails it.
    static func isInstalled(_ folder: URL, lockfile: URL) -> Bool {
        let fm = FileManager.default
        switch lockfile.lastPathComponent {
        case "Podfile.lock":
            return fm.contentsEqual(atPath: folder.appendingPathComponent("Manifest.lock").path, andPath: lockfile.path)
        case "pnpm-lock.yaml":
            return fm.contentsEqual(atPath: folder.appendingPathComponent(".pnpm/lock.yaml").path, andPath: lockfile.path)
        default:
            func packages(_ url: URL) -> [String: [String: Any]]? {
                guard let data = try? Data(contentsOf: url),
                      let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
                return object["packages"] as? [String: [String: Any]]
            }
            guard let pinned = packages(lockfile),
                  let installed = packages(folder.appendingPathComponent(".package-lock.json")) else { return false }
            func identity(_ entry: [String: Any]) -> String? { entry["version"] as? String ?? entry["resolved"] as? String }
            // Optional packages for other platforms are pinned but never installed here.
            let required = pinned.filter { !$0.key.isEmpty && $0.value["optional"] as? Bool != true }
            return required.allSatisfy { key, entry in installed[key].map(identity) == identity(entry) }
                && installed.allSatisfy { key, entry in pinned[key].map(identity) == identity(entry) }
        }
    }

    /// The repository's checkouts (`git worktree list`), the main one first.
    static func checkouts(of worktree: String, git: String = "/usr/bin/git") -> [String] {
        guard let listed = StorageUpkeep.Git.run(git, ["-C", worktree, "worktree", "list", "--porcelain"], timeout: 15),
              listed.succeeded else { return [] }
        return StorageUpkeep.parseWorktrees(listed.output)
            .filter { !$0.bare && !$0.prunable && FileManager.default.fileExists(atPath: $0.path) }
            .map(\.path)
    }

    /// Which of `paths` (relative, folders ending in "/") git ignores in `checkout`.
    static func ignoredPaths(_ paths: [String], in checkout: String, git: String) -> Set<String> {
        guard !paths.isEmpty,
              let result = StorageUpkeep.Git.run(git, ["-C", checkout, "check-ignore", "--no-index", "--"] + paths,
                                                 timeout: 30),
              result.status == 0 || result.status == 1 else { return [] }
        return Set(result.output.split(separator: "\n").map(String.init))
    }

    // MARK: - Sweeping

    /// A shared package cache, and how the sweep keeps it in bounds.
    struct SharedCache {
        enum Trim {
            /// Removes the cache's least recently changed entries (folders `depth` levels down)
            /// idle for `idle`, until it is under its cap.
            case leastRecent(depth: Int, idle: TimeInterval)
            /// Removes every entry idle for `idle`, whatever the size.
            case idleEntries(idle: TimeInterval)
            /// Runs the tool's own cleanup (npm cache verify, pnpm store prune) when over its cap.
            case command(String, [String])
            /// Gradle: the caches and wrapper of Gradle versions no build used for `idle`.
            case gradleVersions(idle: TimeInterval)
        }

        var name: String
        var path: URL
        var cap: Int64?
        var trim: Trim
        /// A running process matching this pattern is using the cache: no trimming then.
        var busyPattern: String
    }

    struct SweepOptions {
        var home: URL
        /// `~/.cache/Cantrip`: agents' ad hoc build folders, removed after `agentIdle`.
        var agentCache: URL
        /// Main checkouts directly inside these: their git-ignored Xcode and SwiftPM output goes
        /// after `repositoryIdle`.
        var repositoryParents: [URL]
        /// Xcode's DerivedData folder and `CANTRIP_BUILD_ROOT`: build folders of projects that no
        /// longer exist (removed worktrees) go after `orphanIdle`.
        var buildRoots: [URL]
        var sharedCaches: [SharedCache]
        var agentIdle: TimeInterval = 3 * 86_400
        var repositoryIdle: TimeInterval = 7 * 86_400
        var orphanIdle: TimeInterval = 86_400
        var now = Date()
        var git = "/usr/bin/git"
        /// Runs a cleanup command; tests replace it.
        var run: (String, [String]) -> Bool = { command, arguments in
            (try? ProcessRunner.run("/usr/bin/env", [command] + arguments, environment: ToolPath.environment(),
                                    errorOutput: .discard, timeout: 600))?.succeeded == true
        }

        static let gigabyte: Int64 = 1 << 30

        static func standard(home: URL = FileManager.default.homeDirectoryForCurrentUser, now: Date = Date(),
                             environment: [String: String] = ProcessInfo.processInfo.environment) -> SweepOptions {
            let library = home.appendingPathComponent("Library")
            var roots = [xcodeDerivedData(home: home)]
            if let buildRoot = buildRoot(environment) { roots.append(buildRoot) }
            let npm = home.appendingPathComponent(".npm")
            let pnpmStore = [library.appendingPathComponent("pnpm/store"),
                             home.appendingPathComponent(".local/share/pnpm/store")]
                .first { FileManager.default.fileExists(atPath: $0.path) } ?? library.appendingPathComponent("pnpm/store")
            let shared = [
                SharedCache(name: "SwiftPM", path: library.appendingPathComponent("Caches/org.swift.swiftpm"),
                            cap: 6 * gigabyte, trim: .leastRecent(depth: 2, idle: 14 * 86_400),
                            busyPattern: #"\b(xcodebuild|swift-build|swift-package)\b"#),
                SharedCache(name: "npm", path: npm.appendingPathComponent("_cacache"), cap: 5 * gigabyte,
                            trim: .command("npm", ["cache", "verify"]),
                            busyPattern: #"\bnpm(-cli\.js)?\s+(ci|install|i|update)\b"#),
                SharedCache(name: "npx", path: npm.appendingPathComponent("_npx"), cap: nil,
                            trim: .idleEntries(idle: 14 * 86_400), busyPattern: #"(?!)"#),
                SharedCache(name: "pnpm", path: pnpmStore, cap: 3 * gigabyte,
                            trim: .command("pnpm", ["store", "prune"]),
                            busyPattern: #"\bpnpm(\.cjs)?\s+(install|i|add|update)\b"#),
                SharedCache(name: "Gradle", path: home.appendingPathComponent(".gradle"), cap: nil,
                            trim: .gradleVersions(idle: 30 * 86_400), busyPattern: #"GradleDaemon|GradleWrapperMain"#),
                SharedCache(name: "CocoaPods", path: library.appendingPathComponent("Caches/CocoaPods"),
                            cap: 4 * gigabyte, trim: .leastRecent(depth: 3, idle: 30 * 86_400),
                            busyPattern: #"\bpod\s+(install|update)\b"#),
            ]
            return SweepOptions(home: home, agentCache: CantripPaths.cache,
                                repositoryParents: [home.appendingPathComponent("Coding"),
                                                    home.appendingPathComponent("Projects")],
                                buildRoots: roots, sharedCaches: shared, now: now)
        }

        /// Where Xcode puts DerivedData (its IDECustomDerivedDataLocation setting, if any).
        static func xcodeDerivedData(home: URL) -> URL {
            if let custom = UserDefaults(suiteName: "com.apple.dt.Xcode")?.string(forKey: "IDECustomDerivedDataLocation"),
               !custom.isEmpty {
                return URL(fileURLWithPath: (custom as NSString).expandingTildeInPath, isDirectory: true)
            }
            return home.appendingPathComponent("Library/Developer/Xcode/DerivedData", isDirectory: true)
        }
    }

    struct CacheSize: Codable, Equatable {
        var name: String
        var path: String
        var bytes: Int64
        var cap: Int64?
        var bytesAfter: Int64
        /// Why trimming didn't run (busy, or the tool is missing).
        var note: String?
    }

    struct Removal: Codable, Equatable {
        var path: String
        var bytes: Int64
        var reason: String
    }

    struct Report: Codable {
        var caches: [CacheSize] = []
        var removed: [Removal] = []
        var errors: [String] = []

        var bytesRemoved: Int64 {
            removed.reduce(0) { $0 + $1.bytes } + caches.reduce(0) { $0 + max($1.bytes - $1.bytesAfter, 0) }
        }

        var count: Int { removed.count + caches.filter { $0.bytesAfter < $0.bytes }.count }
    }

    static func sweep(_ o: SweepOptions, processes: StorageUpkeep.ProcessSnapshot, dryRun: Bool,
                      log: (String) -> Void = { _ in }) -> Report {
        var report = Report()
        let verb = dryRun ? "would remove" : "removed"
        func remove(_ url: URL, reason: String) {
            let bytes = StorageUpkeep.allocatedSize(url)
            if !dryRun {
                do { try StorageUpkeep.removeTree(url) } catch {
                    report.errors.append("\(url.path): \(error.localizedDescription)")
                    return
                }
            }
            report.removed.append(Removal(path: url.path, bytes: bytes, reason: reason))
            log("build cache \(url.path) \(verb): \(StorageUpkeep.format(bytes)), \(reason)")
        }

        // Agents' ad hoc DerivedData and package clones in ~/.cache/Cantrip.
        for found in buildFolders(in: o.agentCache, maxDepth: 3) {
            let idle = idleSince(found.url, shape: found.shape)
            guard o.now.timeIntervalSince(idle) >= o.agentIdle, !processes.uses(found.url.path) else { continue }
            remove(found.url, reason: "agent \(found.shape.label) unused for \(days(o.now, idle)) days")
        }

        // Git-ignored Xcode and SwiftPM output inside checkouts.
        for parent in o.repositoryParents {
            for name in (try? FileManager.default.contentsOfDirectory(atPath: parent.path))?.sorted() ?? [] {
                let repository = parent.appendingPathComponent(name)
                guard StorageUpkeep.isRealDirectory(repository),
                      FileManager.default.fileExists(atPath: repository.appendingPathComponent(".git").path) else { continue }
                for found in buildFolders(in: repository, maxDepth: 4, enteringCheckouts: true) {
                    let idle = idleSince(found.url, shape: found.shape)
                    guard o.now.timeIntervalSince(idle) >= o.repositoryIdle, !processes.uses(found.url.path),
                          isIgnored(found.url, git: o.git) else { continue }
                    remove(found.url, reason: "\(found.shape.label) unused for \(days(o.now, idle)) days")
                }
            }
        }

        // Build folders whose project is gone, in Xcode's DerivedData and the build root.
        for root in o.buildRoots {
            for found in buildFolders(in: root, maxDepth: 3) where found.shape == .derivedData {
                guard let workspace = workspacePath(found.url), isGone(workspace) else { continue }
                let idle = idleSince(found.url, shape: found.shape)
                guard o.now.timeIntervalSince(idle) >= o.orphanIdle, !processes.uses(found.url.path) else { continue }
                remove(found.url, reason: "its project \(workspace) no longer exists")
            }
        }

        for cache in o.sharedCaches {
            guard FileManager.default.fileExists(atPath: cache.path.path) else { continue }
            report.caches.append(trim(cache, o, processes: processes, dryRun: dryRun, report: &report, log: log))
        }
        return report
    }

    private static func trim(_ cache: SharedCache, _ o: SweepOptions, processes: StorageUpkeep.ProcessSnapshot,
                             dryRun: Bool, report: inout Report, log: (String) -> Void) -> CacheSize {
        let bytes = StorageUpkeep.allocatedSize(cache.path)
        var size = CacheSize(name: cache.name, path: cache.path.path, bytes: bytes, cap: cache.cap, bytesAfter: bytes)
        let busy = processes.commandLines.contains {
            $0.range(of: cache.busyPattern, options: .regularExpression) != nil
        }
        let verb = dryRun ? "would remove" : "removed"
        func removeEntry(_ url: URL, _ entryBytes: Int64, _ why: String) -> Bool {
            if !dryRun {
                do { try StorageUpkeep.removeTree(url) } catch {
                    report.errors.append("\(url.path): \(error.localizedDescription)")
                    return false
                }
            }
            log("\(cache.name) cache entry \(url.path) \(verb): \(StorageUpkeep.format(entryBytes)), \(why)")
            return true
        }
        switch cache.trim {
        case .idleEntries(let idle):
            for entry in entries(of: cache.path, depth: 1) where o.now.timeIntervalSince(entry.changed) >= idle {
                guard !processes.uses(entry.url.path) else { continue }
                let entryBytes = StorageUpkeep.allocatedSize(entry.url)
                if removeEntry(entry.url, entryBytes, "unused for \(days(o.now, entry.changed)) days") {
                    size.bytesAfter -= entryBytes
                }
            }
        case .leastRecent(let depth, let idle):
            guard let cap = cache.cap, bytes > cap else { break }
            guard !busy else { size.note = "over its cap but in use by a build"; break }
            for entry in entries(of: cache.path, depth: depth).sorted(by: { $0.changed < $1.changed }) {
                guard size.bytesAfter > cap else { break }
                guard o.now.timeIntervalSince(entry.changed) >= idle else { break }
                let entryBytes = StorageUpkeep.allocatedSize(entry.url)
                if removeEntry(entry.url, entryBytes, "least recently used (cap \(StorageUpkeep.format(cap)))") {
                    size.bytesAfter -= entryBytes
                }
            }
            if size.bytesAfter > cap { size.note = "still over its cap: the rest was used in the last \(Int(idle / 86_400)) days" }
        case .command(let command, let arguments):
            guard let cap = cache.cap, bytes > cap else { break }
            guard !busy else { size.note = "over its cap but in use by an install"; break }
            log("\(cache.name) cache over its cap (\(StorageUpkeep.format(bytes))): \(dryRun ? "would run" : "running") "
                + ([command] + arguments).joined(separator: " "))
            guard !dryRun else { break }
            if o.run(command, arguments) {
                size.bytesAfter = StorageUpkeep.allocatedSize(cache.path)
            } else {
                size.note = "\(command) \(arguments.joined(separator: " ")) failed"
            }
        case .gradleVersions(let idle):
            guard !busy else {
                if !gradleVersions(cache.path, o.now, idle).isEmpty { size.note = "a Gradle daemon is running" }
                break
            }
            for version in gradleVersions(cache.path, o.now, idle) {
                for url in version.folders {
                    let entryBytes = StorageUpkeep.allocatedSize(url)
                    if removeEntry(url, entryBytes, "Gradle \(version.name) unused for \(Int(idle / 86_400))+ days") {
                        size.bytesAfter -= entryBytes
                    }
                }
            }
        }
        return size
    }

    /// Gradle versions with a `caches/<version>` folder unchanged for `idle`, with the folders
    /// they own (their caches and their wrapper distributions).
    static func gradleVersions(_ gradle: URL, _ now: Date, _ idle: TimeInterval) -> [(name: String, folders: [URL])] {
        let fm = FileManager.default
        let caches = gradle.appendingPathComponent("caches")
        let dists = gradle.appendingPathComponent("wrapper/dists")
        let distNames = (try? fm.contentsOfDirectory(atPath: dists.path)) ?? []
        var versions: [(String, [URL])] = []
        for name in ((try? fm.contentsOfDirectory(atPath: caches.path)) ?? []).sorted()
        where name.range(of: #"^\d+(\.\d+)+$"#, options: .regularExpression) != nil {
            let folder = caches.appendingPathComponent(name)
            guard now.timeIntervalSince(newestChange(folder, depth: 2)) >= idle else { continue }
            let wrappers = distNames.filter { $0.hasPrefix("gradle-\(name)-") }.map { dists.appendingPathComponent($0) }
            versions.append((name, [folder] + wrappers))
        }
        return versions
    }

    /// Folders `depth` levels down in `root`, with their newest change.
    static func entries(of root: URL, depth: Int) -> [(url: URL, changed: Date)] {
        var level = [root]
        for _ in 0..<depth {
            level = level.flatMap { folder in
                ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])
                    .map { folder.appendingPathComponent($0) }
                    .filter(StorageUpkeep.isRealDirectory)
            }
        }
        return level.map { ($0, newestChange($0, depth: 1)) }
    }

    // MARK: - Build folders

    enum Shape: String {
        case derivedData, packageClones

        var label: String { self == .derivedData ? "DerivedData" : "SwiftPM checkouts" }
    }

    /// What xcodebuild writes into a DerivedData folder, and SwiftPM into a clones folder
    /// (`-clonedSourcePackagesDirPath`, `SourcePackages`). A folder holding anything else isn't one.
    private static let derivedDataNames: Set<String> = [
        "info.plist", "Build", "Logs", "SourcePackages", "ModuleCache.noindex", "Index.noindex", "TextIndex",
        "CompilationCache.noindex", "SDKExplicitPrecompiledModules", "SDKStatCaches.noindex", "ExplicitPrecompiledModules",
        "TestResults", "SymbolCache.noindex", ".DS_Store",
    ]
    private static let packageCloneNames: Set<String> = [
        "checkouts", "repositories", "artifacts", "registry", "workspace-state.json", "Package.resolved", ".lock",
        ".DS_Store",
    ]

    static func shape(of url: URL) -> Shape? {
        guard let names = try? Set(FileManager.default.contentsOfDirectory(atPath: url.path)), !names.isEmpty else {
            return nil
        }
        if names.isSubset(of: derivedDataNames),
           workspacePath(url) != nil || (names.contains("Logs") && names.contains("SourcePackages")) {
            return .derivedData
        }
        if names.isSubset(of: packageCloneNames), names.contains("checkouts"), names.contains("repositories") {
            return .packageClones
        }
        return nil
    }

    /// DerivedData and package-clone folders in `root`, not looking inside them or dependency
    /// folders. Checkouts below the root (submodules) are searched only when `enteringCheckouts`.
    static func buildFolders(in root: URL, maxDepth: Int, enteringCheckouts: Bool = false) -> [(url: URL, shape: Shape)] {
        let keys: [URLResourceKey] = [.isDirectoryKey, .isSymbolicLinkKey]
        guard let walker = FileManager.default.enumerator(at: root, includingPropertiesForKeys: keys, options: [],
                                                          errorHandler: { _, _ in true }) else { return [] }
        let base = root.standardizedFileURL.pathComponents.count
        var found: [(URL, Shape)] = []
        for case let url as URL in walker {
            guard let values = try? url.resourceValues(forKeys: Set(keys)), values.isDirectory == true,
                  values.isSymbolicLink != true else { continue }
            let name = url.lastPathComponent
            if [".git", "node_modules", "Pods"].contains(name) || name.hasSuffix(".xcodeproj")
                || name.hasSuffix(".xcworkspace") || name.hasSuffix(".app") {
                walker.skipDescendants()
                continue
            }
            if let shape = shape(of: url) {
                found.append((url, shape))
                walker.skipDescendants()
                continue
            }
            let depth = url.standardizedFileURL.pathComponents.count - base
            // Elsewhere a checkout below the root keeps its own lifecycle (worktrees go with their tab).
            if depth >= maxDepth
                || (!enteringCheckouts && FileManager.default.fileExists(atPath: url.appendingPathComponent(".git").path)) {
                walker.skipDescendants()
            }
        }
        return found
    }

    /// The project a DerivedData folder belongs to, from its `info.plist`.
    static func workspacePath(_ derivedData: URL) -> String? {
        guard let data = try? Data(contentsOf: derivedData.appendingPathComponent("info.plist")),
              let plist = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any],
              let path = plist["WorkspacePath"] as? String, !path.isEmpty else { return nil }
        return path
    }

    /// Gone for good: missing, and not on a volume that is merely unmounted right now.
    static func isGone(_ path: String) -> Bool {
        guard !FileManager.default.fileExists(atPath: path) else { return false }
        let components = URL(fileURLWithPath: path).pathComponents
        if components.count > 2, components[1] == "Volumes" {
            return FileManager.default.fileExists(atPath: "/Volumes/" + components[2])
        }
        return true
    }

    /// When a build last used the folder: Xcode's `LastAccessedDate`, or the newest change near its
    /// top. A resolve that changes nothing writes nothing in SwiftPM's clones, but git reads each
    /// checkout's index, so its access time counts too.
    static func idleSince(_ url: URL, shape: Shape) -> Date {
        var newest = newestChange(url, depth: shape == .derivedData ? 2 : 1)
        if shape == .packageClones {
            let checkouts = url.appendingPathComponent("checkouts")
            for name in (try? FileManager.default.contentsOfDirectory(atPath: checkouts.path)) ?? [] {
                for file in [".git/index", ".git/HEAD"] {
                    var info = stat()
                    guard stat(checkouts.appendingPathComponent(name).appendingPathComponent(file).path, &info) == 0 else { continue }
                    newest = max(newest, Date(timeIntervalSince1970: TimeInterval(info.st_atimespec.tv_sec)))
                }
            }
        }
        if shape == .derivedData,
           let data = try? Data(contentsOf: url.appendingPathComponent("info.plist")),
           let plist = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any],
           let accessed = plist["LastAccessedDate"] as? Date {
            newest = max(newest, accessed)
        }
        return newest
    }

    /// The newest modification date of `url` and the folders and files up to `depth` levels inside.
    static func newestChange(_ url: URL, depth: Int) -> Date {
        let fm = FileManager.default
        var newest = (try? url.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate)
            ?? .distantPast
        guard depth > 0 else { return newest }
        for name in (try? fm.contentsOfDirectory(atPath: url.path)) ?? [] {
            let child = url.appendingPathComponent(name)
            let values = try? child.resourceValues(forKeys: [.contentModificationDateKey, .isDirectoryKey,
                                                             .isSymbolicLinkKey])
            if let date = values?.contentModificationDate { newest = max(newest, date) }
            if values?.isDirectory == true, values?.isSymbolicLink != true, depth > 1 {
                newest = max(newest, newestChange(child, depth: depth - 1))
            }
        }
        return newest
    }

    /// Whether the git checkout holding `url` ignores it (nothing tracked inside is ever removed).
    static func isIgnored(_ url: URL, git: String) -> Bool {
        var folder = url.deletingLastPathComponent()
        while folder.path != "/" {
            if FileManager.default.fileExists(atPath: folder.appendingPathComponent(".git").path) {
                let relative = url.standardizedFileURL.pathComponents
                    .dropFirst(folder.standardizedFileURL.pathComponents.count).joined(separator: "/")
                guard let result = StorageUpkeep.Git.run(git, ["-C", folder.path, "check-ignore", "-q", "--", relative + "/"],
                                                         timeout: 15) else { return false }
                // check-ignore exits 0 only when ignored; a tracked file inside makes it 1.
                guard result.status == 0 else { return false }
                guard let tracked = StorageUpkeep.Git.run(git, ["-C", folder.path, "ls-files", "--", relative],
                                                          timeout: 15), tracked.succeeded else { return false }
                return tracked.output.isEmpty
            }
            folder = folder.deletingLastPathComponent()
        }
        return false
    }

    private static func days(_ now: Date, _ since: Date) -> Int {
        Int(now.timeIntervalSince(since) / 86_400)
    }
}
